head.script:
// gridView.readCSV(options) 의 options.popupUrl 로 지정하는 커스텀 CSV 파일 선택 팝업 화면
//  - 엔진 기본 팝업창(uiplugin/grid/upload/csvfileUpload.html) 대신 이 화면이 열리는지 확인하는 용도
//  - 실제 업로드까지 수행하려면 엔진 규약(파일 input + __uploadForm__ 전송 + returnData 처리)에 맞게 구현해야 한다
scwin.onpageload = function() {
    var strQuery = document.location.search;
    if (strQuery.charAt(0) === "?") strQuery = strQuery.substring(1);

    var arrParam = strQuery.split("&");
    var arrResult = [];
    for (var i = 0; i < arrParam.length; i++) {
        if (arrParam[i] === "") continue;
        arrResult.push(decodeURIComponent(arrParam[i]));
    }

    txt_param.setValue("readCSV 가 전달한 파라미터 : " + (arrResult.length === 0 ? "없음" : arrResult.join(" , ")));
};

scwin.btn_closeSelf_onclick = function() {
    window.close();
};
